head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/mgt.js");
scwin.vScrenID = 'ULDMGT10108.gfm';
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.fn_code1_sync = function() {
    var url1 = "/tbmccdval.do?method=searchTbmcCdval&inputMessageId=tbmccdval&outputMessageId=tbmccdval&CD_ID=00715";
    MxDataSet_code1.DataID = encodeURI(url1);

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code1.reset();
    //ShowWin(MxGrid_1);
    var url2 = "/tbmccdval.do?method=searchTbmcCdval&inputMessageId=tbmccdval&outputMessageId=tbmccdval&CD_ID=01110";
    MxDataSet_code2.DataID = encodeURI(url2);

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code2.reset();
    var url3 = "/tbmccdval.do?method=searchTbmcCdval&inputMessageId=tbmccdval&outputMessageId=tbmccdval&CD_ID=01034";
    MxDataSet_code3.DataID = encodeURI(url3);

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code3.reset();
};
scwin.fn_list_sync = function() {
    if (txb_date1.getValue() == "") {
        alert("시작일을 지정하여주십시요");
        return;
    }
    if (txb_date2.getValue() == "") {
        alert("종료일을 지정하여주십시요");
        return;
    }

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var cdCase1 = "&LIST_BZ_TP_CD=" + MxDataSet_code1.NameValue(MxCombo1.Index + 1, "CD_VAL");

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var cdCase2 = "&LIST_PROCS_STAT_CD=" + MxDataSet_code2.NameValue(MxCombo2.Index + 1, "CD_VAL");

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var cdCase3 = "&LD_MKT_TP_CD=" + MxDataSet_code3.NameValue(MxCombo3.Index + 1, "CD_VAL");
    var cdCase4 = "&ISUR_CD=" + ISUR_CD.getValue();
    var cdCase5 = "&DDTM_FROM=" + txb_date1.getValue() + "&DDTM_TO=" + txb_date2.getValue() + "&DDTM_CD=" + MxRadio.getValue();
    var url1 = "/listprocsstat.do?method=searchListProcsStat&inputMessageId=listprocsstat&outputMessageId=listprocsstat&" + cdCase1 + cdCase2 + cdCase3 + cdCase4 + cdCase5 + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    MxDataSet_stat.DataID = encodeURI(url1);

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_stat.reset();
    $c.cm.ShowWin(grid_stat);
};
scwin.fn_log_sync = function(sval) {
    var url1 = "/listprocslog.do?method=searchListProcsLog&inputMessageId=listprocslog&outputMessageId=listprocslog&BZ_PROCS_NO=" + sval;
    MxDataSet_log.DataID = encodeURI(url1);

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_log.reset();
    $c.cm.ShowWin(grid_log);
};



/*---------------------------------------------------------------------------------------------------------*/
scwin.js_com_Isurcd; //발행사코드
scwin.js_com_Isurnm; //발행사명

	//----W-Craft WebSquare 변환 확인: Provider----//
scwin.js_com_market = frame.Provider("/top").ps_market; //운영관리는 "" 로 처리 상장공시처리에서는 세션으로 처리
if (scwin.js_com_market != "1" && scwin.js_com_market != "2") scwin.js_com_market = "";
//if (typeof(js_com_market)=="undefined") {js_com_market = ""; }else{ js_com_market = js_market; }
scwin.js_com_left;
scwin.js_com_top;

	//----W-Craft WebSquare 변환 확인: Focus----//
scwin.stFocusGrid = false;
$c.cm.IsurTagetPos = function(grdObj, grdObj2, Tg) {
    var cL = 7;
    var cT = 53;
    if (Tg == "G") {
        cL = 3;
        cT = 22;
    }
    scwin.js_com_left = grdObj.style.left;
    scwin.js_com_left = scwin.js_com_left.substring(0, scwin.js_com_left.length - 2);
    scwin.js_com_left = eval(scwin.js_com_left) + cL;
    scwin.js_com_top = grdObj.style.top;
    scwin.js_com_top = scwin.js_com_top.substring(0, scwin.js_com_top.length - 2);
    scwin.js_com_top = eval(scwin.js_com_top) + cT;
};
$c.cm.fn_com_grid_pos = function(grdObj, grdObj2) {
    scwin.js_com_Isurcd = grdObj; //발행사코드
    scwin.js_com_Isurnm = grdObj2; //발행사명
    scwin.IsurTagetPos(grdObj, grdObj2, 'G');
    Grd_com_isur.style.left = scwin.js_com_left;
    Grd_com_isur.style.top = scwin.js_com_top;
};
$c.cm.IsurcdSearch = function(grdObj, grdObj2) {
    scwin.js_com_Isurcd = grdObj; //발행사코드
    scwin.js_com_Isurnm = grdObj2; //발행사명
    scwin.IsurTagetPos(grdObj, grdObj2, 'E');

	//----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
    frame.CreateDialogFrame("virWinSave", "/common/ULDCOM00007.gfm", "발행회사검색창", scwin.js_com_left, scwin.js_com_top, 295, 400, "tool");
};
$c.cm.isurSearch_Rtn = function(pJongCode, pJongNm) {
    scwin.js_com_Isurcd.value = pJongCode;
    scwin.js_com_Isurnm.value = pJongNm;
};
$c.cm.fn_com_isur_sync = function() {
    var url = "/isurcd.do?method=searchIsurCd&inputMessageId=isurcd&outputMessageId=isurcd&LIST_STAT_CD=Y&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.js_com_market;
    MxDataSet_com_isur.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_com_isur.reset();
};
$c.cm.fn_com_isur = function(grdObj, grdObj2) {
    Grd_com_isur.style.display = "none";
    scwin.fn_com_grid_pos(grdObj, grdObj2);
    MxDataSet_com_isur.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=isurcd";

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_com_isur.reset();
    scwin.fn_com_isur_sync();
};
$c.cm.fn_com_Confirm_set = function() {

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var pJongCode = MxDataSet_com_isur.NameValue(MxDataSet_com_isur.RowPosition, "ISUR_CD");

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var pJongNm = MxDataSet_com_isur.NameValue(MxDataSet_com_isur.RowPosition, "COM_ABBRV");
    scwin.js_com_Isurcd.value = pJongCode;
    scwin.js_com_Isurnm.value = pJongNm;

	//----W-Craft WebSquare 변환 확인: Focus----//
    scwin.stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
$c.cm.fn_com_isur_nm = function(keyCode) {
    var cnt = 0;
    var len = scwin.js_com_Isurcd.getValue().length;
    var txtVal = scwin.js_com_Isurcd.getValue().toUpperCase();
    var foColum = 1;
    Grd_com_isur.Redraw = "false";
    if (len > 1) {
        if (isNaN(txtVal)) {
            foColum = 1;
        } else {
            foColum = 2;
        }
    }
    if (foColum == 1) {
        MxDataSet_com_isur.SortExpr = "+COM_ABBRV";
        MxDataSet_com_isur.Sort();
        for (i = 1; i <= MxDataSet_com_isur.countrow; i++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
            var name = MxDataSet_com_isur.NameValue(i, "COM_ABBRV").substring(0, len).toUpperCase();
            if (txtVal <= name) {
                cnt = i;
                break;
            }
        }
    } else {
        MxDataSet_com_isur.SortExpr = "+ISUR_CD";
        MxDataSet_com_isur.Sort();
        for (i = 1; i <= MxDataSet_com_isur.countrow; i++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
            var name = MxDataSet_com_isur.NameValue(i, "ISUR_CD").substring(0, len).toUpperCase();
            if (txtVal <= name) {
                cnt = i;
                break;
            }
        }
    }
    Grd_com_isur.Redraw = "true";
    MxDataSet_com_isur.Rowposition = cnt + 11;
    MxDataSet_com_isur.Rowposition = cnt;
};
$c.stockSearch.isNumber = function(sVal) {
    // 숫자인지 확인
    if (('0' < sVal) || ('9' > sVal)) {
        return true;
    } else {
        return false;
    }
};


/*-----------------------------------------------------------------------------------------------------*/

scwin.isur_cd_onblur = function() {

	//----W-Craft WebSquare 변환 확인: Focus----//
    if (scwin.stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (ISUR_CD.getValue() == "") {
        isur_nm.setValue("");
    }
};
scwin.isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "";
};
scwin.isur_cd_onkeyup = function(e) {
    if (window.event.keyCode == 40) {
        //아래화살표눌렀을때 그리드로 포커스

	//----W-Craft WebSquare 변환 확인: Focus----//
        Grd_com_isur.Focus();
    } else {
        if (window.event.keyCode == 13) {
            scwin.fn_com_Confirm_set();
        } else {
            scwin.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_stat_OnLoadCompleted = function(rowcount) {
    textbox_1.setValue("총 " + rowcount + "건");
    $c.cm.CloseWin(rowcount, grid_stat);

	//----W-Craft WebSquare 변환 확인: ClearData----//
    MxDataSet_log.ClearData();
};
scwin.MxDataSet_log_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grid_log);

	//----W-Craft WebSquare 변환 확인: Focus----//
    grid_stat.Focus();
};
scwin.gform_onload = function() {
    MxRadio.setValue(0);
    $c.libRoundPanel.PanelToGroupBox_01(panel_1);
    MxDataSet_code1.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code1.reset();
    MxDataSet_code2.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code2.reset();
    MxDataSet_code3.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code3.reset();
    MxDataSet_stat.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=listprocsstat";

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_stat.reset();
    MxDataSet_log.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=listprocslog";

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_log.reset();
    scwin.fn_code1_sync();
    scwin.fn_com_isur(isur_cd, isur_nm); //발행사Autofill를 위한 스크립트

	//----W-Craft WebSquare 변환 확인: toDaySet----//
    toDaySet(txb_date1);

	//----W-Craft WebSquare 변환 확인: toDaySet----//
    toDaySet(txb_date2);
};
scwin.btn_sys_search_onclick = function(e) {
    scwin.fn_list_sync();
};
scwin.btn_cal_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: popUpCalendar----//
    popUpCalendar(txb_date_bg1, 'txb_date1', 'yyyymmdd'); //alert('image_2.onclick');

};
scwin.image_1_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: popUpCalendar----//
    popUpCalendar(txb_date_bg2, 'txb_date2', 'yyyymmdd'); //alert('image_2.onclick');

};
scwin.grid_stat_OnClick = function(row, colid) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var sCd = MxDataSet_stat.NameValue(row, "BZ_PROCS_NO");
    scwin.fn_log_sync(sCd);
};
scwin.image_6_onclick = function(e) {
    scwin.IsurcdSearch(isur_cd, isur_nm);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        scwin.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    scwin.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

	//----W-Craft WebSquare 변환 확인: Focus----//
scwin.Grd_com_isur_OnSetFocus = function() {

	//----W-Craft WebSquare 변환 확인: Focus----//
    scwin.stFocusGrid = true;
};

	//----W-Craft WebSquare 변환 확인: Focus----//
scwin.Grd_com_isur_OnKillFocus = function() {

	//----W-Craft WebSquare 변환 확인: Focus----//
    scwin.stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
